import {requestJson,clientOrigin,validCredential,browserTimers,browserClock} from '../http-transport.js';
import {RuntimeApiError,identifier} from '../validation.js';
import * as v from './validation.js';
/** Separate volatile read audience; no cache, timers, provider credentials or mutation methods. */
export class CollaborationApiClient{
 #origin;#fetch;#timers;#clock;#timeout;#token='';#account=false;#generation=0;
 /** @type {Set<AbortController>} */#pending=new Set();
 /** @param {import('./contracts').ClientOptions} options */constructor(options){this.#origin=clientOrigin(options);this.#account=options.access==='account';this.#fetch=options.fetchImpl??globalThis.fetch.bind(globalThis);this.#timers=options.timers??browserTimers;this.#clock=options.clock??browserClock;this.#timeout=options.timeoutMs??5000;if(!Number.isInteger(this.#timeout)||this.#timeout<100||this.#timeout>30000)throw new RuntimeApiError('CONFIGURATION');}
 get hasCredential(){return !!this.#token;}
 /** @param {string} token */authorize(token){if(!validCredential(token,this.#account))throw new RuntimeApiError('CONFIGURATION');this.clearCredential();this.#token=token;}
 clearCredential(){this.#token='';this.#generation++;for(const c of this.#pending)c.abort();}
 dispose(){this.clearCredential();}
 /** @param {import('./contracts').Query} q @param {readonly string[]} keys */#query(q,keys){const input=v.record(q),params=new URLSearchParams();for(const key of Object.keys(input)){if(!keys.includes(key))throw new RuntimeApiError('VALIDATION');const value=input[key];if(key==='limit'){if(typeof value!=='number'||!Number.isInteger(value)||value<1||value>20)throw new RuntimeApiError('VALIDATION');params.set(key,String(value));}else if(key==='cursor')params.set(key,v.cursor(value));else if(key==='afterPosition')params.set(key,v.position(value));else if(key==='authority'){if(!['NATIVE','EXTERNAL'].includes(String(value)))throw new RuntimeApiError('VALIDATION');params.set(key,String(value));}else if(key==='status'){if(!v.SESSION.includes(String(value)))throw new RuntimeApiError('VALIDATION');params.set(key,String(value));}else params.set(key,identifier(value));}return params.size?'?'+params:'';}
 /** @template T @param {string} path @param {(value:unknown)=>T} parse @param {import('./contracts').Options} options @returns {Promise<T>} */async #get(path,parse,options){const c=new AbortController(),generation=this.#generation,abort=()=>c.abort();options.signal?.addEventListener('abort',abort,{once:true});if(options.signal?.aborted)c.abort();try{if(!this.#token)throw new RuntimeApiError('AUTH_REQUIRED');this.#pending.add(c);const value=await requestJson(this.#origin+'/api/v1/collaboration-activity'+path,{fetchImpl:this.#fetch,timers:this.#timers,clock:this.#clock,timeoutMs:this.#timeout,headers:{Authorization:'Bearer '+this.#token},signal:c.signal,httpError:res=>new RuntimeApiError(res.status===409?'STALE_SNAPSHOT':res.status===401?'AUTH_REQUIRED':res.status===403?'FORBIDDEN':res.status===404?'NOT_FOUND':res.status===429?'RATE_LIMITED':res.status>=500?'SERVER':'VALIDATION')});if(c.signal.aborted||generation!==this.#generation)throw new RuntimeApiError('CANCELLED');return parse(value);}catch(error){if(generation===this.#generation&&error instanceof RuntimeApiError&&['AUTH_REQUIRED','FORBIDDEN'].includes(error.code))this.clearCredential();throw error;}finally{this.#pending.delete(c);options.signal?.removeEventListener('abort',abort);}}
 /** @param {import('./contracts').Query} [q] @param {import('./contracts').Options} [o] */async list(q={},o={}){return this.#get(this.#query(q,['limit','after','authority','status','agentId']),value=>{const r=v.record(value);if(r.schemaVersion!==2)throw new RuntimeApiError('SCHEMA');return v.page(r,v.summary,s=>s.id);},o);}
 /** @param {string} id @param {import('./contracts').Query} [q] @param {import('./contracts').Options} [o] */async agent(id,q={},o={}){id=identifier(id);return this.#get('/agents/'+id+this.#query(q,['limit','after','externalAfter']),value=>v.agentView(value,id),o);}
 /** @param {string} id @param {import('./contracts').Query} [q] @param {import('./contracts').Options} [o] */async snapshot(id,q={},o={}){id=identifier(id);return this.#get('/'+id+'/snapshot'+this.#query(q,['limit','participantsAfter','delegationsAfter','externalAfter']),value=>v.snapshot(value,id),o);}
 /** @param {string} id @param {import('./contracts').Query} [q] @param {import('./contracts').Options} [o] */async timeline(id,q={},o={}){return this.#get('/'+identifier(id)+'/timeline'+this.#query(q,['limit','cursor']),v.timeline,o);}
 /** @param {string} id @param {string} afterPosition @param {import('./contracts').Options} [o] */async events(id,afterPosition,o={}){const after=v.position(afterPosition);return this.#get('/'+identifier(id)+'/events?limit=20&afterPosition='+after,value=>{const page=v.events(value);if(BigInt(page.nextPosition)<BigInt(after)||page.items.some(e=>BigInt(e.position)<=BigInt(after)))throw new RuntimeApiError('STALE_SNAPSHOT');return page;},o);}
}
